class Solution:
    def minAbbreviation(self, target: str, dictionary: List[str]) -> str:
        m = len(target)
        words = [w for w in dictionary if len(w) == m]
        def abbr(mask):
            parts, i = [], 0
            while i < m:
                if mask >> i & 1:
                    parts.append(target[i]); i += 1
                else:
                    j = i
                    while j < m and not (mask >> j & 1): j += 1
                    parts.append(str(j - i)); i = j
            return ''.join(parts)
        def conflicts(mask):
            for w in words:
                ok = True
                for i in range(m):
                    if mask >> i & 1 and w[i] != target[i]:
                        ok = False; break
                if ok: return True
            return False
        best, blen = None, float('inf')
        for mask in range(1 << m):
            pc = bin(mask).count('1')
            runs = sum(1 for i in range(m + 1)
                       if ((mask >> i & 1) == 0) and (i == 0 or (mask >> (i - 1) & 1)))
            ln = pc + runs
            if ln < blen and not conflicts(mask):
                blen, best = ln, abbr(mask)
        return best

