class Solution {
public:
    string minAbbreviation(string target, vector<string>& dictionary) {
        int m = target.size();
        vector<string> words;
        for (auto& w : dictionary) if ((int)w.size() == m) words.push_back(w);
        auto abbr = [&](int mask) {
            string r; int i = 0;
            while (i < m) {
                if (mask >> i & 1) { r += target[i++]; }
                else { int j = i; while (j < m && !(mask >> j & 1)) j++; r += to_string(j - i); i = j; }
            }
            return r;
        };
        auto conflicts = [&](int mask) {
            for (auto& w : words) {
                bool ok = true;
                for (int i = 0; i < m; i++)
                    if ((mask >> i & 1) && w[i] != target[i]) { ok = false; break; }
                if (ok) return true;
            }
            return false;
        };
        string best; int blen = INT_MAX;
        for (int mask = 0; mask < (1 << m); mask++) {
            int pc = __builtin_popcount(mask), runs = 0;
            for (int i = 0; i <= m; i++)
                if (!(mask >> i & 1) && (i == 0 || (mask >> (i - 1) & 1))) runs++;
            if (pc + runs < blen && !conflicts(mask)) { blen = pc + runs; best = abbr(mask); }
        }
        return best;
    }
};

