class Solution {
    public String minAbbreviation(String target, String[] dictionary) {
        int m = target.length();
        List<String> words = new ArrayList<>();
        for (String w : dictionary) if (w.length() == m) words.add(w);
        for (int mask = 0; mask < (1 << m); mask++) {
            int pc = Integer.bitCount(mask), runs = 0;
            for (int i = 0; i <= m; i++)
                if (((mask >> i) & 1) == 0 && (i == 0 || ((mask >> (i - 1)) & 1) == 1)) runs++;
            if (pc + runs >= bestLen) continue;
            boolean bad = false;
            outer: for (String w : words) {
                for (int i = 0; i < m; i++)
                    if (((mask >> i) & 1) == 1 && w.charAt(i) != target.charAt(i)) continue outer;
                bad = true; break;
            }
            if (!bad) { bestLen = pc + runs; bestMask = mask; }
        }
        StringBuilder sb = new StringBuilder(); int i = 0;
        while (i < m) {
            if (((bestMask >> i) & 1) == 1) sb.append(target.charAt(i++));
            else { int j = i; while (j < m && ((bestMask >> j) & 1) == 0) j++; sb.append(j - i); i = j; }
        }
        return sb.toString();
    }
    private int bestLen = Integer.MAX_VALUE, bestMask = 0;
}

