        diffs = []
        for w in dictionary:
            if len(w) == m:
                d = 0
                for i in range(m):
                    if w[i] != target[i]: d |= 1 << i
                diffs.append(d)
        self.best = (1 << m) - 1
        self.blen = m
        def dfs(mask):
            if bin(mask).count('1') >= self.blen: return
            for d in diffs:
                if mask & d == 0: break
            else:
                self.best, self.blen = mask, bin(mask).count('1')
                return
            x = d
            while x:
                b = x & -x
                dfs(mask | b)
                x ^= b
        dfs(0)
        mask, res, i = self.best, [], 0
        while i < m:
            if mask >> i & 1: res.append(target[i]); i += 1
            else:
                j = i
                while j < m and not (mask >> j & 1): j += 1
                res.append(str(j - i)); i = j
        return ''.join(res)

